import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export function normalizeText(text) {
  if (typeof text !== 'string' || !text.trim() || text.trim().length > 4000)
    throw new Error('text must contain 1–4000 characters');
  return text.trim();
}
export function normalizeTag(tag) {
  if (typeof tag !== 'string' || !tag.trim() || tag.trim().length > 40)
    throw new Error('tags must be nonempty strings of at most 40 characters');
  return tag.trim().toLowerCase();
}
export function normalizeTags(tags) {
  if (!Array.isArray(tags)) throw new Error('tags must be an array');
  return [...new Set(tags.map(normalizeTag))].sort();
}
export function validateId(id) {
  if (!Number.isSafeInteger(id) || id < 1) throw new Error('id must be a positive integer');
  return id;
}
export function openStore(path) {
  mkdirSync(dirname(path), {recursive:true});
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000;
    CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY,text TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS tags(name TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS note_tags(note_id INTEGER REFERENCES notes(id) ON DELETE CASCADE,tag TEXT REFERENCES tags(name),PRIMARY KEY(note_id,tag));`);
  const transaction = fn => {
    db.exec('SAVEPOINT mutation');
    try { const result = fn(); db.exec('RELEASE mutation'); return result; }
    catch (error) { db.exec('ROLLBACK TO mutation; RELEASE mutation'); throw error; }
  };
  const getNote = id => {
    validateId(id);
    const row = db.prepare('SELECT * FROM notes WHERE id=?').get(id);
    if (!row) return null;
    return {id:Number(row.id), text:row.text, createdAt:row.created_at, updatedAt:row.updated_at,
      tags:db.prepare('SELECT tag FROM note_tags WHERE note_id=? ORDER BY tag').all(id).map(r=>r.tag)};
  };
  const attach = (id, tags) => {
    for (const tag of tags) {
      db.prepare('INSERT OR IGNORE INTO tags VALUES(?)').run(tag);
      db.prepare('INSERT INTO note_tags VALUES(?,?)').run(id, tag);
    }
  };
  return {
    transaction,
    createNote(text, tags=[]) {
      text = normalizeText(text); tags = normalizeTags(tags);
      return transaction(() => {
        const now = new Date().toISOString();
        const id = Number(db.prepare('INSERT INTO notes(text,created_at,updated_at) VALUES(?,?,?)').run(text,now,now).lastInsertRowid);
        attach(id, tags);
        return getNote(id);
      });
    },
    getNote,
    listNotes({q,tag,limit=50,offset=0}={}) {
      if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('limit must be an integer from 1 to 100');
      if (!Number.isSafeInteger(offset) || offset < 0) throw new Error('offset must be a nonnegative integer');
      if (q !== undefined && typeof q !== 'string') throw new Error('q must be a string');
      const conditions = [], params = [];
      if (q !== undefined) { conditions.push('instr(lower(text), lower(?)) > 0'); params.push(q); }
      if (tag !== undefined) { conditions.push('EXISTS (SELECT 1 FROM note_tags WHERE note_id=notes.id AND tag=?)'); params.push(normalizeTag(tag)); }
      return db.prepare(`SELECT id FROM notes ${conditions.length ? 'WHERE '+conditions.join(' AND ') : ''} ORDER BY id DESC LIMIT ? OFFSET ?`)
        .all(...params,limit,offset).map(r=>getNote(Number(r.id)));
    },
    updateNote(id, patch) {
      validateId(id);
      if (!patch || typeof patch !== 'object' || Array.isArray(patch)) throw new Error('patch must be an object');
      const text = Object.hasOwn(patch,'text') ? normalizeText(patch.text) : undefined;
      const tags = Object.hasOwn(patch,'tags') ? normalizeTags(patch.tags) : undefined;
      return transaction(() => {
        const old = getNote(id);
        if (!old) return null;
        const now = new Date(Math.max(Date.now(), Date.parse(old.updatedAt)+1)).toISOString();
        db.prepare('UPDATE notes SET text=?,updated_at=? WHERE id=?').run(text ?? old.text,now,id);
        if (tags !== undefined) { db.prepare('DELETE FROM note_tags WHERE note_id=?').run(id); attach(id,tags); }
        return getNote(id);
      });
    },
    deleteNote(id) { validateId(id); return db.prepare('DELETE FROM notes WHERE id=?').run(id).changes > 0; },
    listTags() { return db.prepare('SELECT tag AS name, COUNT(*) AS count FROM note_tags GROUP BY tag ORDER BY tag').all().map(r=>({name:r.name,count:Number(r.count)})); },
    close() { db.close(); }
  };
}

import { normalizeText, normalizeTags } from './store.mjs';

// Validate the entire batch, including tags, before any mutation.
export function importNotes(store, records) {
  if (!Array.isArray(records)) throw new Error('notes must be an array');
  const prepared = records.map(record => {
    if (!record || typeof record !== 'object' || Array.isArray(record)) throw new Error('invalid note record');
    return {text:normalizeText(record.text), tags:normalizeTags(record.tags === undefined ? [] : record.tags)};
  });
  const create = () => prepared.map(record => store.createNote(record.text, record.tags));
  return typeof store.transaction === 'function' ? store.transaction(create) : create();
}

export function allNotes(store) {
  const result = [];
  for (let offset=0;;offset+=100) {
    const batch = store.listNotes({limit:100,offset});
    result.push(...batch);
    if (batch.length < 100) return result;
  }
}
export function exportNotes(store) {
  return {version:1,notes:allNotes(store).reverse().map(({text,tags})=>({text,tags}))};
}

import { createInterface } from 'node:readline';
import { parseArgs } from 'node:util';
import { openStore } from './store.mjs';
import { importNotes, exportNotes, allNotes } from './import.mjs';

const {values} = parseArgs({options:{db:{type:'string',default:'data/notes.sqlite'}}});
const store = openStore(values.db);
const text = {type:'string',minLength:1,maxLength:4000};
const tags = {type:'array',items:{type:'string',minLength:1,maxLength:40}};
const id = {type:'integer',minimum:1};
const specs = [
  ['notes_create',{text,tags},['text'], a=>store.createNote(a.text,a.tags)],
  ['notes_get',{id},['id'], a=>store.getNote(a.id)],
  ['notes_list',{q:{type:'string'},tag:{type:'string'},limit:{type:'integer',minimum:1,maximum:100},offset:{type:'integer',minimum:0}},[], a=>store.listNotes(a)],
  ['notes_update',{id,text,tags},['id'], a=>{ const {id,...patch}=a; return store.updateNote(id,patch); }],
  ['notes_delete',{id},['id'], a=>store.deleteNote(a.id)],
  ['tags_list',{},[], ()=>store.listTags()],
  ['notes_export',{},[], ()=>exportNotes(store)],
  ['notes_import',{notes:{type:'array',items:{type:'object',properties:{text,tags},required:['text'],additionalProperties:false}}},['notes'], a=>importNotes(store,a.notes)]
];
const tools = specs.map(([name,properties,required])=>({name,description:name.replaceAll('_',' '),inputSchema:{type:'object',properties,required,additionalProperties:false}}));
function dispatch(method, params={}) {
  switch (method) {
    case 'initialize': return {protocolVersion:'2024-11-05',capabilities:{tools:{},resources:{}},serverInfo:{name:'quick-notes',version:'1.0.0'}};
    case 'notifications/initialized': return {};
    case 'ping': return {};
    case 'tools/list': return {tools};
    case 'tools/call': {
      try {
        if (!params || typeof params !== 'object') throw new Error('invalid tool parameters');
        const spec = specs.find(s=>s[0]===params.name);
        if (!spec) throw new Error('unknown tool');
        const args = params.arguments ?? {};
        if (!args || typeof args !== 'object' || Array.isArray(args)) throw new Error('arguments must be an object');
        if (spec[2].some(key=>!Object.hasOwn(args,key)) || Object.keys(args).some(key=>!Object.hasOwn(spec[1],key))) throw new Error('invalid tool arguments');
        return {content:[{type:'text',text:JSON.stringify(spec[3](args))}]};
      } catch (error) { return {isError:true,content:[{type:'text',text:error.message}]}; }
    }
    case 'resources/list': return {resources:[{uri:'notes://all',name:'All notes',mimeType:'application/json'}]};
    case 'resources/read':
      if (params?.uri !== 'notes://all') throw {code:-32002,message:'Unknown resource'};
      return {contents:[{uri:'notes://all',mimeType:'application/json',text:JSON.stringify(allNotes(store))}]};
    default: throw {code:-32601,message:'Method not found'};
  }
}
const send = message => process.stdout.write(JSON.stringify(message)+'\n');
const lines = createInterface({input:process.stdin,crlfDelay:Infinity});
lines.on('line', line => {
  if (!line.trim()) return;
  let request;
  try { request=JSON.parse(line); }
  catch { send({jsonrpc:'2.0',id:null,error:{code:-32700,message:'Parse error'}}); return; }
  if (!request || Array.isArray(request) || request.jsonrpc !== '2.0' || typeof request.method !== 'string') {
    send({jsonrpc:'2.0',id:request?.id ?? null,error:{code:-32600,message:'Invalid Request'}}); return;
  }
  try {
    const result=dispatch(request.method,request.params);
    if (Object.hasOwn(request,'id')) send({jsonrpc:'2.0',id:request.id,result});
  } catch (error) {
    if (Object.hasOwn(request,'id')) send({jsonrpc:'2.0',id:request.id,error:{code:error.code ?? -32602,message:error.message}});
  }
});
lines.on('close',()=>store.close());

import { createServer } from 'node:http';
import { parseArgs } from 'node:util';
import { openStore, validateId } from './store.mjs';
import { importNotes, exportNotes } from './import.mjs';

const {values} = parseArgs({options:{db:{type:'string',default:'data/notes.sqlite'},port:{type:'string',default:'8080'}}});
const port = Number(values.port);
if (!Number.isInteger(port) || port < 0 || port > 65535) throw new Error('invalid port');
const store = openStore(values.db);
const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const layout = (title, body) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${escape(title)}</title><style>body{font:16px system-ui;max-width:850px;margin:2rem auto;padding:0 1rem;color:#172334;background:#f6f8fb}article,section{background:white;padding:1rem;margin:1rem 0;border:1px solid #ccd6e0;border-radius:8px}textarea{width:95%;min-height:90px}input,button,select{padding:.5rem;margin:.3rem}a{color:#1254a0}.text{white-space:pre-wrap;overflow-wrap:anywhere}.error{color:#a00}label{display:block}.tags{color:#456}nav{margin:1rem 0}</style></head><body><h1><a href="/">Quick Notes</a></h1>${body}</body></html>`;
const form = (action, note={text:'',tags:[]}) => `<form method="post" action="${action}"><label>Text<textarea name="text" required maxlength="4000">${escape(note.text)}</textarea></label><label>Tags (comma separated)<input name="tags" value="${escape(note.tags.join(', '))}"></label><button>Save note</button></form>`;
const fail = (status,message) => { throw Object.assign(new Error(message),{status}); };
const requireNote = id => store.getNote(id) ?? fail(404,'Note not found');
const integerParam = (params,key,fallback) => {
  if (!params.has(key)) return fallback;
  const raw=params.get(key);
  if (!/^\d+$/.test(raw)) fail(400,`${key} must be an integer`);
  return Number(raw);
};
const filters = params => ({...(params.has('q') ? {q:params.get('q')} : {}),...(params.has('tag') && params.get('tag') !== '' ? {tag:params.get('tag')} : {})});
async function readBody(req, json) {
  let body='';
  for await (const chunk of req) {
    body+=chunk.toString();
    if (Buffer.byteLength(body)>1024*1024) fail(400,'Request body too large');
  }
  if (!json) return new URLSearchParams(body);
  let value;
  try { value=JSON.parse(body); } catch { fail(400,'Invalid JSON'); }
  if (!value || typeof value !== 'object' || Array.isArray(value)) fail(400,'JSON body must be an object');
  return value;
}
const server = createServer(async (req,res) => {
  const json = (value,status=200) => {res.writeHead(status,{'Content-Type':'application/json; charset=utf-8'});res.end(JSON.stringify(value));};
  const html = (value,status=200) => {res.writeHead(status,{'Content-Type':'text/html; charset=utf-8'});res.end(value);};
  const redirect = () => {res.writeHead(303,{Location:'/'});res.end();};
  let url;
  try {
    url=new URL(req.url,'http://localhost');
    const path=url.pathname, method=req.method;
    if (path === '/api/notes') {
      if (method === 'GET') return json(store.listNotes({...filters(url.searchParams),limit:integerParam(url.searchParams,'limit',50),offset:integerParam(url.searchParams,'offset',0)}));
      if (method === 'POST') {const body=await readBody(req,true);return json(store.createNote(body.text,body.tags),201);}
    }
    const apiMatch=path.match(/^\/api\/notes\/(\d+)$/);
    if (apiMatch && ['GET','PATCH','DELETE'].includes(method)) {
      const id=validateId(Number(apiMatch[1])); requireNote(id);
      if (method==='GET') return json(store.getNote(id));
      if (method==='DELETE') return json(store.deleteNote(id));
      return json(store.updateNote(id,await readBody(req,true)));
    }
    if (path==='/api/tags' && method==='GET') return json(store.listTags());
    if (path==='/api/export' && method==='GET') return json(exportNotes(store));
    if (path==='/api/import' && method==='POST') return json(importNotes(store,(await readBody(req,true)).notes),201);
    if (path==='/' && method==='GET') {
      const page=integerParam(url.searchParams,'page',1);
      if (page<1 || !Number.isSafeInteger(page) || !Number.isSafeInteger((page-1)*20)) fail(400,'invalid page');
      const filter=filters(url.searchParams);
      const notes=store.listNotes({...filter,limit:20,offset:(page-1)*20});
      const next=store.listNotes({...filter,limit:1,offset:page*20}).length>0;
      const link = p => '/?'+new URLSearchParams({...filter,page:String(p)});
      return html(layout('Quick Notes', `<form method="get"><label>Search<input name="q" value="${escape(filter.q ?? '')}"></label><label>Tag<select name="tag"><option value="">All tags</option>${store.listTags().map(t=>`<option value="${escape(t.name)}" ${filter.tag?.trim().toLowerCase()===t.name?'selected':''}>${escape(t.name)} (${t.count})</option>`).join('')}</select></label><button>Filter</button></form><section><h2>Create note</h2>${form('/notes')}</section><h2>Notes</h2>${notes.length ? notes.map(n=>`<article><div class="text">${escape(n.text)}</div><p class="tags">${n.tags.map(escape).join(', ')}</p><small>${escape(n.updatedAt)}</small> <a href="/notes/${n.id}/edit">Edit</a><form method="post" action="/notes/${n.id}/delete"><button>Delete</button></form></article>`).join('') : '<p>No notes found.</p>'}<nav>${page>1?`<a href="${escape(link(page-1))}">Previous</a>`:''} Page ${page} ${next?`<a href="${escape(link(page+1))}">Next</a>`:''}</nav>`));
    }
    const editMatch=path.match(/^\/notes\/(\d+)\/edit$/);
    if (editMatch && method==='GET') {
      const note=requireNote(validateId(Number(editMatch[1])));
      return html(layout('Edit note',`<h2>Edit note</h2>${form('/notes/'+note.id,note)}`));
    }
    const postMatch=path.match(/^\/notes\/(\d+)(\/delete)?$/);
    if (method==='POST' && (path==='/notes' || postMatch)) {
      const id=postMatch ? validateId(Number(postMatch[1])) : null;
      if (id) requireNote(id);
      if (postMatch?.[2]) {store.deleteNote(id);return redirect();}
      const body=await readBody(req,false);
      const text=body.get('text');
      const rawTags=body.get('tags') ?? '';
      const tags=rawTags.trim()==='' ? [] : rawTags.split(',');
      if (id) store.updateNote(id,{text,tags}); else store.createNote(text,tags);
      return redirect();
    }
    fail(404,'Not found');
  } catch (error) {
    const status=error.status ?? 400;
    if (url?.pathname.startsWith('/api/')) json({error:error.message},status);
    else html(layout('Error',`<h2 class="error">${escape(error.message)}</h2><p><a href="/">Back to notes</a></p>`),status);
  }
});
server.listen(port,'127.0.0.1',()=>console.log(JSON.stringify({port:server.address().port})));
function shutdown() { server.close(()=>{store.close();}); }
process.on('SIGINT',shutdown);
process.on('SIGTERM',shutdown);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { openStore } from '../src/store.mjs';
import { importNotes, exportNotes, allNotes } from '../src/import.mjs';

test('normalization, literal search, pagination and atomic mutations', () => {
  const s=openStore(':memory:');
  try {
    const n=s.createNote('  Hello 50%_ <x>  ',[' Work ','work','HOME']);
    assert.deepEqual(n.tags,['home','work']);
    assert.equal(n.text,'Hello 50%_ <x>');
    s.createNote('hello other',['work']);
    assert.deepEqual(s.listNotes({q:'50%_'}).map(x=>x.id),[n.id]);
    assert.equal(s.listNotes({q:'HELLO',tag:' WORK '}).length,2);
    assert.equal(s.listNotes({limit:1,offset:1})[0].id,n.id);
    for (const text of ['',null,4,'x'.repeat(4001)]) assert.throws(()=>s.createNote(text));
    for (const tags of [null,'work',[''],[2],['x'.repeat(41)]]) {
      assert.throws(()=>s.createNote('bad',tags));
      assert.throws(()=>s.updateNote(n.id,{text:'changed',tags}));
      assert.deepEqual(s.getNote(n.id),n);
    }
    for (const options of [{limit:0},{limit:101},{limit:1.5},{offset:-1},{q:2}]) assert.throws(()=>s.listNotes(options));
    const updated=s.updateNote(n.id,{tags:['new']});
    assert.equal(updated.createdAt,n.createdAt);
    assert.ok(updated.updatedAt>n.updatedAt);
    assert.deepEqual(updated.tags,['new']);
    assert.ok(s.updateNote(n.id,{}).updatedAt>updated.updatedAt);
    assert.equal(s.updateNote(999,{}),null);
    assert.equal(s.getNote(999),null);
    assert.equal(s.deleteNote(999),false);
    assert.equal(s.deleteNote(n.id),true);
    assert.deepEqual(s.listTags(),[{name:'work',count:1}]);
  } finally {s.close();}
});

test('shared import validates every field before writing, and exports all records', () => {
  const s=openStore(':memory:');
  try {
    for (const record of [{text:''},{text:'bad',tags:['ok',null]},{text:'bad',tags:null}]) {
      assert.throws(()=>importNotes(s,[{text:'valid',tags:['ok']},record]));
      assert.deepEqual(s.listNotes(),[]);
    }
    const notes=importNotes(s,Array.from({length:125},(_,i)=>({text:'note '+i,tags:[' TEST ']})));
    assert.equal(notes.length,125);
    assert.equal(allNotes(s).length,125);
    assert.equal(exportNotes(s).notes[0].text,'note 0');
    assert.equal(exportNotes(s).notes.at(-1).text,'note 124');
    assert.throws(()=>s.transaction(()=>{s.createNote('rolled back');throw Error('abort');}));
    assert.equal(allNotes(s).length,125);
  } finally {s.close();}
});

test('disk persistence, nested directory creation and foreign key cascade', () => {
  const dir=mkdtempSync('test/.storage-');
  const path=join(dir,'nested','notes.sqlite');
  try {
    let s=openStore(path);const n=s.createNote('persistent',['unique']);s.close();
    s=openStore(path);assert.equal(s.getNote(n.id).text,'persistent');
    s.deleteNote(n.id);s.close();
    const db=new DatabaseSync(path);
    assert.equal(db.prepare('SELECT COUNT(*) AS n FROM note_tags').get().n,0);
    db.close();
  } finally {rmSync(dir,{recursive:true,force:true});}
});

import { test } from 'node:test';
